"""Thin llama.cpp wrapper — the ONE place model choice is resolved.

The rest of the app talks to `get_client().generate(...)` / `.see(...)` and never
imports llama_cpp directly. This keeps the Day-1 1.3B <-> 8B decision a config
change, and lets the whole app run in "mock" mode before any weights exist.

Roles:
    "generate" -> text/reasoning model (question gen, answer keys, reports)
    "vision"   -> multimodal model (read a chapter photo -> text)
Under MODE="tiny" both roles resolve to the same 1.3B model.
"""

from __future__ import annotations

import functools
import json
from typing import Optional

import config


class LLMClient:
    """Wraps a single GGUF model for one role. Lazy-loads on first use."""

    def __init__(self, role: str):
        self.role = role
        self.model_key = config.model_for(role)
        self._llm = None          # llama_cpp.Llama, loaded lazily
        self._chat_handler = None

    # -- loading --------------------------------------------------------------
    def _ensure_loaded(self):
        if config.MODE == "mock" or self.model_key is None:
            return  # mock mode: never load weights
        if self._llm is not None:
            return

        from llama_cpp import Llama  # imported lazily so mock mode needs no dep
        from huggingface_hub import hf_hub_download  # noqa: F401  (used below)

        spec = config.MODELS[self.model_key]
        model_path = _resolve_gguf(spec["repo_id"], spec["filename"])

        # Vision needs the multimodal projector (mmproj) + a chat handler.
        chat_handler = None
        if self.role == "vision" and spec.get("mmproj"):
            mmproj_path = _resolve_gguf(spec["repo_id"], spec["mmproj"])
            # MiniCPM-V uses the llava/minicpmv multimodal chat handler family.
            # NOTE (Day 1): if vision is ignored in your llama.cpp build, fall
            # back to the transformers vision path — see implementation_plan.md.
            from llama_cpp.llama_chat_format import MiniCPMv26ChatHandler
            chat_handler = MiniCPMv26ChatHandler(clip_model_path=str(mmproj_path))

        self._chat_handler = chat_handler
        self._llm = Llama(
            model_path=str(model_path),
            chat_handler=chat_handler,
            n_ctx=config.N_CTX,
            n_gpu_layers=config.N_GPU_LAYERS,
            verbose=False,
        )

    # -- text generation ------------------------------------------------------
    def generate(self, prompt: str, *, system: Optional[str] = None,
                 temperature: float = config.TEMPERATURE,
                 max_tokens: int = config.MAX_TOKENS) -> str:
        """Single-turn text generation. Returns the assistant message text."""
        if config.MODE == "mock" or self.model_key is None:
            return _mock_generate(prompt, system)

        self._ensure_loaded()
        messages = []
        if system:
            messages.append({"role": "system", "content": system})
        messages.append({"role": "user", "content": prompt})
        out = self._llm.create_chat_completion(
            messages=messages, temperature=temperature, max_tokens=max_tokens,
        )
        return out["choices"][0]["message"]["content"].strip()

    def generate_json(self, prompt: str, *, system: Optional[str] = None,
                      **kw) -> dict | list:
        """Generate and parse a JSON object/array. Tolerant of code fences."""
        raw = self.generate(prompt, system=system, **kw)
        return _extract_json(raw)

    # -- vision ---------------------------------------------------------------
    def see(self, image_path: str, prompt: str) -> str:
        """Ask a question about an image (OCR / chapter understanding)."""
        if config.MODE == "mock" or self.model_key is None:
            return _mock_vision(image_path, prompt)

        self._ensure_loaded()
        import base64

        with open(image_path, "rb") as f:
            b64 = base64.b64encode(f.read()).decode()
        data_uri = f"data:image/png;base64,{b64}"
        out = self._llm.create_chat_completion(
            messages=[{
                "role": "user",
                "content": [
                    {"type": "image_url", "image_url": {"url": data_uri}},
                    {"type": "text", "text": prompt},
                ],
            }],
            temperature=0.2,
            max_tokens=config.MAX_TOKENS,
        )
        return out["choices"][0]["message"]["content"].strip()


# -- module-level cache -------------------------------------------------------
@functools.lru_cache(maxsize=4)
def get_client(role: str = "generate") -> LLMClient:
    """Return a cached client for a role ('generate' | 'vision')."""
    return LLMClient(role)


# -- helpers ------------------------------------------------------------------
def _resolve_gguf(repo_id: str, filename_glob: str):
    """Download (cached) the GGUF matching a glob and return its local path."""
    from huggingface_hub import hf_hub_download, list_repo_files

    files = [f for f in list_repo_files(repo_id) if _glob_match(f, filename_glob)]
    if not files:
        raise FileNotFoundError(
            f"No file matching {filename_glob!r} in {repo_id}. "
            "Check the exact GGUF filename on the Hub (Day-1 task)."
        )
    return hf_hub_download(repo_id=repo_id, filename=files[0],
                           local_dir=str(config.MODELS_DIR))


def _glob_match(name: str, pattern: str) -> bool:
    import fnmatch
    return fnmatch.fnmatch(name, pattern) or fnmatch.fnmatch(name.lower(), pattern.lower())


def _extract_json(text: str):
    """Pull the first JSON object/array out of a model response."""
    import re
    fence = re.search(r"```(?:json)?\s*(.*?)```", text, re.S)
    if fence:
        text = fence.group(1)
    start = min((i for i in (text.find("{"), text.find("[")) if i != -1), default=-1)
    if start == -1:
        raise ValueError(f"No JSON found in model output:\n{text[:300]}")
    depth, open_ch = 0, text[start]
    close_ch = "}" if open_ch == "{" else "]"
    for i in range(start, len(text)):
        if text[i] == open_ch:
            depth += 1
        elif text[i] == close_ch:
            depth -= 1
            if depth == 0:
                return json.loads(text[start:i + 1])
    return json.loads(text[start:])  # let json raise a useful error


# -- mock outputs (MODE="mock") ----------------------------------------------
def _mock_generate(prompt: str, system: Optional[str]) -> str:
    """Deterministic stub so the UI/agent flow runs with no model."""
    if "JSON" in (system or "") + prompt or "json" in prompt.lower():
        return json.dumps([
            {"q": "[MOCK] State Ohm's law.", "type": "short",
             "answer": "V = IR; current is proportional to voltage.", "marks": 2},
            {"q": "[MOCK] Unit of resistance is ____.", "type": "fill",
             "answer": "ohm", "marks": 1},
        ])
    return "[MOCK OUTPUT] " + prompt[:120]


def _mock_vision(image_path: str, prompt: str) -> str:
    return ("[MOCK VISION] Chapter appears to cover: Electricity — current, "
            "voltage, resistance, Ohm's law, series and parallel circuits.")

