"""Turn a Pack into print-ready HTML (and optionally PDF).

HTML is the source of truth (always works, prints cleanly from a browser).
PDF export is best-effort via weasyprint; the app falls back to HTML if the
library isn't installed (notably on Windows).
"""

from __future__ import annotations

import html
from pathlib import Path

import config

_CSS = """
* { box-sizing: border-box; }
body { font-family: 'Segoe UI', system-ui, sans-serif; color: #1a1a2e;
       max-width: 800px; margin: 0 auto; padding: 24px; line-height: 1.5; }
h1 { font-size: 22px; margin: 0 0 4px; }
.meta { color: #555; font-size: 13px; margin-bottom: 16px; }
.section { page-break-inside: avoid; margin: 18px 0; }
.section h2 { font-size: 16px; border-bottom: 2px solid #4f46e5;
              padding-bottom: 4px; color: #4f46e5; }
ol { margin: 8px 0 8px 20px; padding: 0; }
li { margin: 6px 0; }
.marks { color: #888; font-size: 12px; }
.key { page-break-before: always; }
.key h2 { color: #059669; border-color: #059669; }
.ans { margin: 6px 0; }
.ans .w { color: #555; font-size: 13px; }
.parent { background: #f5f5ff; border-left: 4px solid #4f46e5;
          padding: 12px 16px; margin-top: 20px; }
.print-hint { color:#aaa; font-size:11px; margin-top:24px; }
"""


def _q_li(q: dict) -> str:
    text = html.escape(str(q.get("q", "")))
    marks = q.get("marks")
    badge = f' <span class="marks">[{marks}m]</span>' if marks else ""
    if q.get("type") == "fill":
        text = text.replace("____", "<u>&nbsp;&nbsp;&nbsp;&nbsp;</u>")
    return f"<li>{text}{badge}</li>"


def pack_to_html(pack) -> str:
    m = pack.meta
    parts = [
        f"<style>{_CSS}</style>",
        f"<h1>Weekly Teaching Pack — {html.escape(str(m.get('chapter')))}</h1>",
        (f'<div class="meta">{html.escape(m.get("board",""))} · Class '
         f'{html.escape(str(m.get("class")))} · {html.escape(str(m.get("subject")))} · '
         f'{html.escape(str(m.get("difficulty")))} · {html.escape(str(m.get("language")))}</div>'),
    ]

    # Sections (group consecutive same-name blocks under one heading)
    last_name = None
    for sec in pack.sections:
        if sec["name"] != last_name:
            if last_name is not None:
                parts.append("</ol></div>")
            parts.append(f'<div class="section"><h2>{html.escape(sec["name"])}</h2><ol>')
            last_name = sec["name"]
        for q in sec["questions"]:
            parts.append(_q_li(q))
    if last_name is not None:
        parts.append("</ol></div>")

    # Answer key
    parts.append('<div class="section key"><h2>Answer Key</h2>')
    for a in pack.answer_key:
        q = html.escape(str(a.get("q", "")))
        ans = html.escape(str(a.get("answer", "")))
        working = a.get("working")
        w = f'<div class="w">{html.escape(str(working))}</div>' if working else ""
        parts.append(f'<div class="ans"><b>Q:</b> {q}<br><b>A:</b> {ans}{w}</div>')
    parts.append("</div>")

    # Parent note
    if pack.parent_note:
        parts.append(f'<div class="parent"><b>Parent Note</b><p>'
                     f'{html.escape(pack.parent_note)}</p></div>')

    parts.append('<div class="print-hint">TutorDesk AI · runs fully on-device · '
                 'Ctrl/Cmd+P to print</div>')
    return "\n".join(parts)


def html_to_pdf(html_str: str, name: str = "teaching_pack") -> Path | None:
    """Best-effort PDF export. Returns path, or None if PDF backend unavailable."""
    out = config.OUTPUT_DIR / f"{name}.pdf"
    try:
        from weasyprint import HTML
        HTML(string=html_str).write_pdf(str(out))
        return out
    except Exception:
        # No PDF backend (e.g. Windows without weasyprint): write HTML instead.
        html_out = config.OUTPUT_DIR / f"{name}.html"
        html_out.write_text(html_str, encoding="utf-8")
        return html_out

